* BANK4 -- Open a new account. All inputs blank to start; ENTER
* validates required fields, mints a 23-digit account number from
* bank_acct_seq, INSERTs the row, and (if opening deposit > 0)
* records a CR opening-deposit transaction. PF3 cancels.
MAP BANK4 SIZE 24x80
  FIELD AT 0,24 LEN 32 PROT BRIGHT COLOR=WHITE     "BRICKS BANK NA - OPEN ACCOUNT"

  FIELD AT 2,2  LEN 76 PROT COLOR=TURQUOISE        "Fill in the form. First / Last / Street / City / State / ZIP required."

  FIELD AT 4,2  LEN 11 PROT COLOR=BLUE             "First name:"
  INPUT FIRST   AT 4,14 LEN 40 UNDERSCORE COLOR=GREEN
  STOP          AT 4,55

  FIELD AT 5,2  LEN 11 PROT COLOR=BLUE             "Last name:"
  INPUT LAST    AT 5,14 LEN 40 UNDERSCORE COLOR=GREEN
  STOP          AT 5,55

  FIELD AT 6,2  LEN 11 PROT COLOR=BLUE             "MI:"
  INPUT MI      AT 6,14 LEN 1  UNDERSCORE COLOR=GREEN
  STOP          AT 6,16

  FIELD AT 8,2  LEN 11 PROT COLOR=BLUE             "Street:"
  INPUT STREET  AT 8,14 LEN 60 UNDERSCORE COLOR=GREEN
  STOP          AT 8,75

  FIELD AT 9,2  LEN 11 PROT COLOR=BLUE             "City:"
  INPUT CITY    AT 9,14 LEN 40 UNDERSCORE COLOR=GREEN
  STOP          AT 9,55

  FIELD AT 10,2 LEN 11 PROT COLOR=BLUE             "State:"
  INPUT STATE   AT 10,14 LEN 2  UNDERSCORE COLOR=GREEN
  STOP          AT 10,17

  FIELD AT 11,2 LEN 11 PROT COLOR=BLUE             "ZIP:"
  INPUT ZIP     AT 11,14 LEN 10 UNDERSCORE COLOR=GREEN
  STOP          AT 11,25

  FIELD AT 13,2 LEN 11 PROT COLOR=BLUE             "Email:"
  INPUT EMAIL   AT 13,14 LEN 60 UNDERSCORE COLOR=GREEN
  STOP          AT 13,75

  FIELD AT 14,2 LEN 11 PROT COLOR=BLUE             "Phone:"
  INPUT PHONE   AT 14,14 LEN 15 UNDERSCORE COLOR=GREEN
  STOP          AT 14,30

  FIELD AT 16,2 LEN 15 PROT COLOR=BLUE             "Opening dep $:"
  INPUT DEPOSIT AT 16,18 LEN 12 UNDERSCORE NUMERIC COLOR=GREEN
  STOP          AT 16,31

  FIELD AT 19,2 LEN 14 PROT COLOR=BLUE             "New account #:"
  FIELD NEWACCT AT 19,17 LEN 23 PROT BRIGHT COLOR=YELLOW

  FIELD MSG     AT 22,2 LEN 76 PROT BRIGHT COLOR=RED
  FIELD AT 23,0 LEN 80 PROT DIM COLOR=BLUE         "ENTER=Create  PF3=Cancel"
  CURSOR        AT 4,15
ENDMAP
